import{f as e,h as t,j as n,n as r}from"./chunks/shared.rYHlazZf.js";var i=JSON.parse(`{"title":"Préparer la collaboration et l’accès des équipes","description":"","frontmatter":{"title":"Préparer la collaboration et l’accès des équipes","docId":"user.cloud.collaboration","translationKey":"user.cloud.collaboration","locale":"fr","audience":"user","featureStatus":"experimental","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"05f448dda78b05027b84b2c03f08a15eb515aee05af79397a1596d7e40ec5d40","translationRevision":"6435fb775f3eab73258d699fbd0745f267e3dcfe87af16f62c59e99fcee35661","order":30},"headers":[],"relativePath":"fr/user/cloud/collaboration.md","filePath":"fr/user/cloud/collaboration.md","lastUpdated":1795731074000}`),a={name:`fr/user/cloud/collaboration.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="prepare-collaboration-and-team-access" tabindex="-1">Préparer la collaboration et l’accès des équipes <a class="header-anchor" href="#prepare-collaboration-and-team-access" aria-label="Permalink to “Préparer la collaboration et l’accès des équipes”">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objectif et prérequis <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to “Objectif et prérequis”">​</a></h2><p>Accordez à un autre opérateur un rôle défini en conservant le contrôle du propriétaire. L’accès distant est fourni par le plugin installable <strong>Remote Control</strong>, et non par un onglet des préférences : il faut une <a href="./account.html">connexion Cloud</a>, un service compatible et le plugin installé pour cet hôte. Commencez avec un accès en lecture seule et une configuration hors production.</p><h2 id="configure-remote-access" tabindex="-1">Configurer l’accès distant <a class="header-anchor" href="#configure-remote-access" aria-label="Permalink to “Configurer l’accès distant”">​</a></h2><ol><li>Installez et activez <code>tiktools.remote-control</code>, puis ouvrez sa page <strong>Remote control</strong>.</li><li>Créez une équipe et inscrivez <strong>ce PC</strong> comme hôte avec un nom d’appareil reconnaissable ; démarrez la liaison de relais et attendez que son état atteigne <code>ready</code>.</li><li>Créez une invitation et transmettez son jeton à usage unique par un canal de confiance. Une invitation n’est pas une session active approuvée.</li><li>Examinez la demande en attente et le rôle demandé. N’approuvez que l’opérateur attendu ; l’autorisation reste <code>pendingHost</code> jusqu’à ce que la liaison de l’hôte la confirme.</li><li>Vérifiez régulièrement les autorisations et les appareils. Révoquez une autorisation dont l’accès n’est plus nécessaire.</li></ol><p>Modifier une définition par délégation, adopter une définition en tant que propriétaire et approuver une exécution déléguée sont des décisions distinctes. Lisez la source enregistrée, les actions référencées et les permissions dans l’examen concerné. Un aperçu de définition seul n’autorise pas un effet.</p><h2 id="prepare-a-controller-device" tabindex="-1">Préparer un appareil contrôleur <a class="header-anchor" href="#prepare-a-controller-device" aria-label="Permalink to “Préparer un appareil contrôleur”">​</a></h2><p>Sur l’appareil contrôleur, connectez-vous avec son propre compte, inscrivez-le comme contrôleur et échangez le jeton d’invitation. Une demande en attente apparaît alors pour le propriétaire. La recherche par pseudonyme nécessite un point de terminaison serveur déployé séparément et peut être indisponible sur le service actuel. Ne supposez pas qu’une recherche échouée signifie que la personne n’a pas de compte, et ne remplacez pas la sélection par un identifiant arbitraire.</p><h2 id="expected-result-and-status" tabindex="-1">Résultat attendu et état <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to “Résultat attendu et état”">​</a></h2><p>Le parcours entre deux comptes (équipe, liaison de l’hôte, invitation, approbation, commande de lecture, révocation) a été vérifié avec un serveur local. Les onglets Collaboration/Équipes des préférences ont été supprimés ; le service de collaboration natif n’a pas d’interface web dans cette version. Le comportement du relais/NAT en production, la recherche par pseudonyme et le fonctionnement LIVE entre deux PC ne sont pas établis ici. Une liaison prête ne prouve pas à elle seule l’application des permissions de bout en bout pour votre action.</p><h2 id="recovery" tabindex="-1">Récupération <a class="header-anchor" href="#recovery" aria-label="Permalink to “Récupération”">​</a></h2><p>Pour des autorisations obsolètes, révoquez l’accès et vérifiez-le à nouveau après l’actualisation de la liaison. Pour des commandes non confirmées, consultez le résultat enregistré avant de réessayer. Arrêtez la liaison ou révoquez l’accès en terminant une session. Excluez les jetons d’invitation et les identifiants secrets des <a href="./../preferences/troubleshooting.html">rapports de diagnostic</a> publics.</p><h2 id="operational-details" tabindex="-1">Détails de fonctionnement <a class="header-anchor" href="#operational-details" aria-label="Permalink to “Détails de fonctionnement”">​</a></h2><p>Chaque commande distante passe par le contrôle de capacités de l’hôte (<code>remote.command.dispatch</code>, <code>remote.pair.list</code>, <code>remote.grant.list</code>, <code>remote.grant.revoke</code>, <code>remote.controller.ticket</code>) ; le plugin ne reçoit jamais d’API de contrôle ni de jeton complet. Un transport actif ou l’appartenance à une équipe ne donnent pas seuls d’accès natif. Observer privilégie la lecture ; moderator ajoute certains contrôles, automationEditor certaines éditions, custom exige une politique explicite revue. Aucun ne donne des scripts/effets illimités. Consultez <a href="./../../developer/collaboration.html#operational-details">rôles et confirmation</a> et <a href="./../../developer/transports.html">transports</a> pour la frontière actuelle.</p>`,14)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};